bicepWiring.resource:
resource keyVault 'Microsoft.KeyVault/vaults@2023-07-01' = {
  name: keyVaultName
  location: location
  properties: {
    sku: { family: 'A', name: 'standard' }
    tenantId: subscription().tenantId
    enableRbacAuthorization: true
    enableSoftDelete: true
    softDeleteRetentionInDays: 7
  }
}

bicepWiring.storeSecret:
resource secret 'Microsoft.KeyVault/vaults/secrets@2023-07-01' = {
  parent: keyVault
  name: 'my-secret'
  properties: { value: secretValue }
}

sdkInitPattern.typescript:
import { SecretClient } from '@azure/keyvault-secrets';
import { DefaultAzureCredential } from '@azure/identity';

const credential = new DefaultAzureCredential();
const url = `https://${process.env.AZURE_KEY_VAULT_NAME}.vault.azure.net`;
const client = new SecretClient(url, credential);

const secret = await client.getSecret('my-secret');
const value = secret.value;
